    }
    for import in &caller.module_uses {
        debit(work, 1)?;
        if import.kind != ModuleUseKind::Function {
            continue;
        }
        let target = authored
            .get(import.persistent_id.as_str())
            .ok_or_else(refusal)?;
        let function = target.function.ok_or_else(refusal)?;
