        }
        debit(work, 1)?;
        Ok(a.ordinal.cmp(&b.ordinal))
    })?;
    let owner = Self {
        caller,
        programs,
        authored,
        sites,
        ledger: match ledger {
            Some(ledger) => Rc::clone(ledger),
            None => super::ledger::Ledger::new(*work)?,
